'use strict';
let importKind='portrait',importSource=null,importPrepared=null;
const assetActions=['行走、待机与倒地','动作组 1（攻击等）','动作组 2（受击等）','动作组 3（结印等）','动作组 4（投掷等）','动作组 5','动作组 6','动作组 7','动作组 8'];
function assetTargetIds(){return model.characters.map(c=>[c.id,model.characterName(c.id)]);}
function assetCanvas(c,img){c.width=img.width;c.height=img.height;c.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(img.pixels),img.width,img.height),0,0);}
function imageDataOf(canvas){const d=canvas.getContext('2d').getImageData(0,0,canvas.width,canvas.height);return{width:d.width,height:d.height,pixels:d.data};}
function fitImage(img,w,h,mode){if(mode==='exact'&&(img.width!==w||img.height!==h))throw Error(`原尺寸模式需要 ${w}×${h} PNG，当前为 ${img.width}×${img.height}`);const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;if(mode==='exact'||mode==='stretch')ctx.drawImage(img,0,0,w,h);else{const s=Math.min(w/img.width,h/img.height),dw=Math.round(img.width*s),dh=Math.round(img.height*s);ctx.drawImage(img,Math.floor((w-dw)/2),Math.floor((h-dh)/2),dw,dh);}return imageDataOf(c);}
function quickSheet(img){const c=document.createElement('canvas');c.width=320;c.height=256;const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;const source=document.createElement('canvas');source.width=img.width;source.height=img.height;source.getContext('2d').drawImage(img,0,0);const data=source.getContext('2d').getImageData(0,0,img.width,img.height).data;for(let f=0;f<20;f++){const x0=Math.round(f%5*img.width/5),x1=Math.round((f%5+1)*img.width/5),y0=Math.round(Math.floor(f/5)*img.height/4),y1=Math.round((Math.floor(f/5)+1)*img.height/4);let left=x1,right=x0,top=y1,bottom=y0;for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(data[(y*img.width+x)*4+3]>=128){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}if(left>right)throw Error(`动作格 ${f+1} 为空，请使用 5 列×4 行动作表`);const w=right-left+1,h=bottom-top+1,scale=Math.min((f<16?30:58)/w,(f<16?50:24)/h),dw=Math.max(1,Math.round(w*scale)),dh=Math.max(1,Math.round(h*scale));ctx.drawImage(img,left,top,w,h,f%5*64+Math.floor((64-dw)/2),Math.floor(f/5)*64+56-dh,dw,dh);}return imageDataOf(c);}
function renderAssetImports(){panel.innerHTML=`<div class="sectionhead"><div><h2>素材导入</h2><p>先选分类和用途，查看转换预览，满意后保存进当前工程。</p></div><span class="badge">原素材保留 · 支持撤销</span></div><div class="assetcategories">${[['palette','色卡'],['portrait','人物头像'],['sprite','战斗人物'],['terrain','地块 / 地形']].map(([v,t])=>`<button data-import-kind="${v}" class="${importKind===v?'primary':''}">${t}</button>`).join('')}</div><div class="card"><div class="importsteps"><span>1 选择目标</span><span>2 打开素材</span><span>3 预览后保存</span></div><div id="importControls"></div><div class="toolbar"><label class="button primary">打开${importKind==='palette'?'色卡文件':'图片 PNG'}<input id="assetFile" type="file" accept="${importKind==='palette'?'.pal,.gpl,.json,.bin,.rgb555':'.png'}"></label><button id="downloadAssetTemplate" ${importKind==='palette'?'hidden':''}>下载当前素材 / 动作模板</button><label class="button">载入素材包 JSON<input id="assetPackFile" type="file" accept=".json"></label></div><p id="assetHelp" class="hint"></p><div class="assetImportPreview"><div><h3>导入前</h3><canvas id="importOriginal" class="checkered"></canvas></div><div><h3>转换后（游戏效果）</h3><canvas id="importResult" class="checkered"></canvas><p id="assetStats" role="status">选择文件后展示尺寸、颜色和透明色。</p><div id="assetSwatches" class="swatches"></div></div></div><p id="assetImportError" role="alert"></p><div class="toolbar"><button id="prepareAsset">重新预览</button><button id="applyAsset" class="primary" disabled>保存此素材</button><button id="saveAssetPack" disabled>导出本次素材包</button></div></div><div class="card"><h3>已导入素材</h3><div id="importedAssetList"></div></div>`;
 panel.querySelectorAll('[data-import-kind]').forEach(b=>b.onclick=()=>{importKind=b.dataset.importKind;importSource=null;importPrepared=null;renderAssetImports();});renderImportControls();renderImportedList();$('#prepareAsset').onclick=()=>run(previewImport);$('#assetFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>16000000)throw Error('文件超过 16 MB，请缩小后再导入');if(importKind==='palette'){const colors=await parsePalette(f);importSource={name:f.name,colors};previewImport();}else{const image=new Image(),url=URL.createObjectURL(f);try{image.src=url;await image.decode();importSource={name:f.name,image};previewImport();}finally{URL.revokeObjectURL(url);}}}catch(err){showImportError(err.message);}e.target.value='';};$('#downloadAssetTemplate').onclick=()=>run(downloadTemplate);$('#applyAsset').onclick=()=>run(()=>{if(!importPrepared)throw Error('请先打开素材并预览');const asset=importPrepared;transaction(`导入${{portrait:'头像',sprite:'战斗人物',terrain:'地块',palette:'色卡'}[importKind]}`,()=>applyImport(asset),false);renderImportedList();$('#assetStats').textContent+=' · 已保存到当前工程';});$('#saveAssetPack').onclick=()=>{if(importPrepared)download(JSON.stringify(importPrepared,null,2),'木叶工房_素材包.json','application/json');};$('#assetPackFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8000000)throw Error('素材包超过 8 MB');const pack=JSON.parse(await f.text());validatePack(pack);transaction('载入素材包',()=>applyImport(pack),false);importPrepared=pack;renderImportedList();notify('素材包已保存到工程，可撤销。');}catch(err){showImportError(err.message);}e.target.value='';};}
function renderImportControls(){const target=`<label>人物<select id="assetCharacter">${opts(assetTargetIds(),47)}</select></label>`,palette=`<label>颜色处理<select id="assetPalette"><option value="auto">自动生成适合本分类的色卡</option>${model.importedAssets().palettes.map((p,i)=>`<option value="${i}">${esc(p.name)}（${p.colors.length} 色）</option>`).join('')}</select></label>`;let html,help;
 if(importKind==='portrait'){html=target+`<label>表情<select id="assetExpression">${opts([[0,'普通'],[1,'默认对话'],[2,'表情 3'],[3,'表情 4'],[4,'表情 5']],1)}</select></label><label><input id="assetAllExpressions" type="checkbox">五种表情一起替换</label><label>尺寸处理<select id="assetFit"><option value="fit">等比放入 80×80（不裁切）</option><option value="exact">原尺寸 80×80</option><option value="stretch">铺满 80×80</option></select></label>`+palette;help='透明 PNG 最适合头像。最多 63 个不透明色，透明像素使用第 1 色；多余颜色会合并，转换后可直接比较。';}
 else if(importKind==='sprite'){html=target+`<label>角色能力<select id="assetProfile"><option value="0">保留本人物原有能力</option>${opts(E.names.slice(1).map((n,i)=>[i+1,'参考'+n]),12)}</select></label><label>导入方式<select id="assetSpriteMode"><option value="template">按原动作模板导入（推荐修改现有动作）</option><option value="quick">快速创建：5 列×4 行，20 格动作表</option></select></label><label>动作<select id="assetAction">${opts(assetActions.map((x,i)=>[i,x]),0)}</select></label>`+palette;help='模板模式：先下载所选人物动作 PNG，修改后保持画布尺寸与动作位置再导入。快速创建：使用 20 格动作表，顺序为正面 3、背面 3、左侧 3、右侧 3、下蹲 2、跳跃 2、倒地 4；自动整理尺寸并生成基础动作。战斗图使用 14 个不透明色，另保留透明色和游戏的阵营标记色。快速模式复用基础动作节奏，不会生成专属忍术演出。';}
 else if(importKind==='terrain'){const m=model.mapData(model.battleIds().includes(stage)?stage:1);html=`<p>放入${model.battleIds().includes(stage)?`当前战场 ${stage}`:'战场 1'}的一个地图格（32×16 像素）</p><label>X<input id="assetX" type="number" min="0" max="${m.width-1}" value="0"></label><label>Y<input id="assetY" type="number" min="0" max="${m.height-1}" value="0"></label><label>通行规则<select id="assetTerrain">${opts([[0,'可通行地面'],[7,'障碍（不可通过）'],[15,'边界（不可通过）']],0)}</select></label><label>尺寸处理<select id="assetFit"><option value="exact">原尺寸 32×16</option><option value="fit">等比放入 32×16</option><option value="stretch">铺满 32×16</option></select></label>`+palette;help='地块由图片、色卡、图块和通行规则一起导入。只改变目标格，图片中透明处使用本图背景色。编辑后可到“关卡地图”继续绘制通行规则。每张地图最多 16 组色卡、1024 个图块，超过会说明原因并阻止保存。';}
 else{html='<label>色卡名称<input id="assetPaletteName" placeholder="例如：凯的绿色衣服"></label>';help='支持 GIMP .gpl、JASC-PAL .pal、GBA 原始 .bin / .rgb555 色卡、木叶工房色卡 JSON。第 1 色保留为透明色；保存后可在头像、人物或地块导入时选用。头像最多 64 色（含透明），战斗人物导入时自动保留阵营标记色；地块最多 16 色。';}
 $('#importControls').innerHTML=html;$('#assetHelp').textContent=help;$('#importControls').onchange=()=>{importPrepared=null;$('#applyAsset').disabled=true;$('#saveAssetPack').disabled=true;if(importSource)run(previewImport);};}
function showImportError(msg){$('#assetImportError').textContent=msg;$('#applyAsset').disabled=true;$('#saveAssetPack').disabled=true;importPrepared=null;}
function selectedPalette(){const v=$('#assetPalette')?.value;return v&&v!=='auto'?model.importedAssets().palettes[+v].colors:undefined;}
function previewImport(){if(!importSource)throw Error('先打开一张 PNG 或色卡文件');try{let asset,meta={};if(importKind==='palette'){asset={name:$('#assetPaletteName').value||importSource.name,colors:importSource.colors};$('#assetStats').textContent=`${asset.colors.length} 色 · 第 1 色为透明色`;$('#assetSwatches').innerHTML=swatches(asset.colors);}
 else{const id=+$('#assetCharacter')?.value||0;let img;if(importKind==='portrait'){img=fitImage(importSource.image,80,80,$('#assetFit').value);meta={id,expression:+$('#assetExpression').value,all:$('#assetAllExpressions').checked};}else if(importKind==='terrain'){img=fitImage(importSource.image,32,16,$('#assetFit').value);meta={stage:model.battleIds().includes(stage)?stage:1,x:+$('#assetX').value,y:+$('#assetY').value,terrain:+$('#assetTerrain').value};}else{const quick=$('#assetSpriteMode').value==='quick',action=+$('#assetAction').value,info=quick?null:model.spriteInfo(id,action);img=quick?quickSheet(importSource.image):fitImage(importSource.image,info.width,info.height,'exact');meta={id,action,quick,profileSource:+$('#assetProfile').value};}assetCanvas($('#importOriginal'),img);asset=E.AssetImport.quantize(img,importKind==='portrait'?63:importKind==='sprite'?14:15,importKind==='sprite'?selectedPalette()?.slice(0,15):selectedPalette());asset.label=importSource.name;assetCanvas($('#importResult'),asset);$('#assetStats').textContent=`${asset.width}×${asset.height} · 原 ${asset.sourceColors} 色 → ${asset.colors} 色＋透明色${importKind==='sprite'?'（另留阵营色）':''} · 游戏使用 RGB555 色彩`;$('#assetSwatches').innerHTML=swatches(asset.palette);asset={width:asset.width,height:asset.height,palette:asset.palette,indices:asset.indices,label:asset.label};}
 importPrepared={format:'naruto-asset-pack',version:1,kind:importKind,meta,asset};$('#assetImportError').textContent='';$('#applyAsset').disabled=false;$('#saveAssetPack').disabled=false;}catch(e){showImportError(e.message);throw e;}}
function swatches(colors){return colors.map((v,i)=>{const c=E.AssetImport.rgb(v);return`<span title="${i===0?'透明':`颜色 ${i}`}" style="background:rgb(${c.slice(0,3).join(',')})">${i===0?'透':''}</span>`;}).join('');}
function validatePack(p){if(p.format!=='naruto-asset-pack'||p.version!==1||!['palette','portrait','sprite','terrain'].includes(p.kind)||!p.meta||!p.asset)throw Error('请选择木叶工房导出的素材包');}
function applyImport(p){validatePack(p);const a=p.asset,m=p.meta;if(p.kind==='palette')model.addPalette(a.name,a.colors);else if(p.kind==='portrait')model.setPortraitAsset(m.id,m.expression,a,m.all);else if(p.kind==='sprite'){m.quick?model.setQuickSpriteAsset(m.id,a):model.setSpriteAsset(m.id,m.action,a);if(m.profileSource)model.setCharacterProfile(m.id,m.profileSource);}else model.setTileAsset(m.stage,m.x,m.y,a,m.terrain);}
function renderImportedList(){const a=model.importedAssets(),rows=[...Object.entries(a.profiles||{}).map(([id,s])=>`角色能力 · ${actorName(+id)}参考${actorName(s)}`),...a.palettes.map(p=>`色卡 · ${p.name} · ${p.colors.length} 色`),...Object.entries(a.portraits).map(([k,v])=>{const[id,e]=k.split(':');return`头像 · ${actorName(+id)} · 表情 ${+e+1} · ${v.label}`;}),...Object.entries(a.sprites).map(([k,v])=>{const[id,ac]=k.split(':');return`战斗人物 · ${actorName(+id)} · ${ac==='quick'?'20 格基础动作':assetActions[+ac]} · ${v.label}`;}),...Object.entries(a.maps).flatMap(([s,v])=>Object.values(v.cells).map(c=>`地块 · 战场 ${s} (${c.x}, ${c.y}) · ${terrainLabel(c.terrain)} · ${c.label}`))];$('#importedAssetList').innerHTML=rows.length?`<ul>${rows.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:'<p class="hint">还没有导入素材。保存后会列在这里，并随“保存工程”一同保存。</p>';}
function downloadTemplate(){let img,name;if(importKind==='portrait'){img=model.renderPortrait(+$('#assetCharacter').value,+$('#assetExpression').value);name='头像_80x80.png';}else if(importKind==='sprite'){const id=+$('#assetCharacter').value,ac=+$('#assetAction').value;img=model.renderSpriteSheet(id,ac);name=`${actorName(id)}_动作${ac}_保持尺寸与位置.png`;}else{const s=model.battleIds().includes(stage)?stage:1,m=model.renderMap(s),c=document.createElement('canvas');assetCanvas(c,m);const tile=document.createElement('canvas');tile.width=32;tile.height=16;tile.getContext('2d').drawImage(c,+$('#assetX').value*32,+$('#assetY').value*16,32,16,0,0,32,16);img=imageDataOf(tile);name='地块_32x16.png';}const c=document.createElement('canvas');assetCanvas(c,img);c.toBlob(b=>download(b,name,'image/png'));}
async function parsePalette(file){const text=await file.text();let colors;if(/\.(bin|rgb555)$/i.test(file.name)||(/\.pal$/i.test(file.name)&&!text.startsWith('JASC-PAL'))){const b=new Uint8Array(await file.arrayBuffer());if(b.length<4||b.length>512||b.length%2)throw Error('GBA 原始色卡须为 4～512 字节的 RGB555 数据');colors=Array.from({length:b.length/2},(_,i)=>b[i*2]|b[i*2+1]<<8);if(colors.some(v=>v>32767))throw Error('原始色卡包含非 RGB555 数据');return colors;}if(file.name.toLowerCase().endsWith('.json')){const p=JSON.parse(text);colors=p.colors||p.palette||p.asset?.colors||p.asset?.palette;if(!Array.isArray(colors))throw Error('JSON 中没有 colors 或 palette 色卡');}else{const lines=text.replace(/\r/g,'').split('\n');if(!/^GIMP Palette|^JASC-PAL/.test(lines[0]))throw Error('请选择 GIMP GPL 或 JASC-PAL 色卡');colors=lines.slice(lines[0]==='JASC-PAL'?3:1).map(l=>l.trim()).filter(l=>/^\d+\s+\d+\s+\d+/.test(l)).map(l=>{const v=l.split(/\s+/).slice(0,3).map(Number);if(v.some(n=>n<0||n>255||!Number.isInteger(n)))throw Error('色卡 RGB 值须在 0～255');return Math.round(v[0]*31/255)|Math.round(v[1]*31/255)<<5|Math.round(v[2]*31/255)<<10;});}if(colors.length<2||colors.length>256||colors.some(c=>!Number.isInteger(c)||c<0||c>32767))throw Error('色卡须包含 2～256 个 RGB555 色值，第 1 色保留为透明');return colors;}
